// Package manifest decodes `harnaas.json`, the committed, hand-edited file in
// which a project declares which harness assets it wants and where they come
// from.
//
// The package covers the document and nothing beyond it: where the file lives,
// and how its bytes become a [Document]. It does not interpret an asset's
// source string, infer a type or an id from a path, default a target list or a
// scope, or check any of them against the harness roster. Those read a decoded
// document and live in the manifest's interpretation layer, which is why this
// package imports no roster and validates no meaning — a field it accepts here
// is one it could read, not one harnaas has agreed to.
//
// # Strict decoding
//
// The manifest is written by a person and reviewed by a team, so an unknown
// field is nearly always a typo and surfacing it immediately is worth the cost
// of refusing to run. That is the whole test: strictness follows who writes the
// file, not what the file is called. `harnaas.lock.json` is machine-written and
// therefore decodes leniently, because a newer binary introduces fields an
// older binary would otherwise reject, bricking the file for everyone still on
// the older version.
//
// The version field is what bounds that trade. It is read on its own, ahead of
// the strict pass, so a manifest written by a newer harnaas is refused with an
// explicit "upgrade harnaas" message rather than a confusing complaint about
// the first field this binary happens not to know.
//
// A decode failure returns no document at all. Half a manifest is not a smaller
// manifest — it is a different one, and installing from it would place a subset
// of what the project declared while reporting success.
//
// # Read-only
//
// Nothing here writes. Apart from `harnaas init` creating the file once, harnaas
// never writes, reformats or normalizes `harnaas.json`: it is the artifact a
// team reviews, and a tool that rewrites it makes its diffs untrustworthy. Every
// remedy this package reports is therefore phrased as the exact edit for a
// person to make, never as a command that would make it for them. A test over
// this package's own sources asserts no write call has crept in.
package manifest

// FileName is the manifest's only accepted name, at the repository root.
//
// It is a constant rather than a flag because the file is a project-level
// declaration: a `--manifest` pointing somewhere else would mean two developers
// in the same repository could install different asset sets and both be right.
const FileName = "harnaas.json"

// SupportedVersion is the manifest schema version this binary understands.
//
// A manifest declaring a greater version is refused with an upgrade message
// rather than read partially, because the fields this binary would silently
// ignore are exactly the ones the newer harnaas added to change what the
// document means.
const SupportedVersion = 1

// Document is a decoded manifest, field for field as written.
//
// Nothing in it has been interpreted: `Harnesses` and each entry's `Targets`
// are the strings the author typed rather than roster ids, and an asset's
// `Type`, `ID` and `Scope` are populated only where the object form declared
// them. An empty field here means "not declared", never "declared as the
// default" — the interpretation layer is what turns the first into the second,
// and it can only do that if decoding kept them distinguishable.
type Document struct {
	// Path is the file the document was decoded from, so a later diagnostic can
	// name it. It is empty for a document decoded from bytes.
	Path string

	// Version is the declared schema version, always a version this binary
	// understands — a greater one fails decoding rather than reaching a caller.
	Version int

	// Harnesses names the harnesses assets target by default. The list states a
	// guarantee ("we guarantee the declared assets work for these"), not
	// exclusivity: assets installed for one harness are routinely visible to
	// another.
	Harnesses []string

	// Sources maps a short key to a source string such as
	// `github:acme/assets@v1.2.0`. The key is what asset entries reference, so a
	// repository and a ref appear exactly once each.
	Sources map[string]string

	// Assets is the declared asset list in document order. Order is preserved
	// because it is the order the author reads in review, and every diagnostic
	// naming an entry names its index in this slice.
	Assets []AssetEntry
}

// AssetEntry is one entry of the `assets` array, in whichever form it was
// written.
//
// The string form carries only a source; the object form may additionally
// declare a type, an id, a target list or a scope, each suppressing what would
// otherwise be inferred or defaulted for that one field.
type AssetEntry struct {
	// Index is the entry's position in the `assets` array. It is not decoded
	// from the document — it is where the entry was found, and it is how every
	// diagnostic points the author at the line to edit, since an entry has no
	// other stable name until its id is known.
	Index int

	// ObjectForm records whether the entry was written as an object rather than
	// a bare source string. Some remedies are only available in the object form,
	// so a message can direct an author there only if it knows they are not
	// already using it.
	ObjectForm bool

	// Source is the entry's source string: the `<sourceKey>:<path>` or
	// `.harnaas/…` form, exactly as written and not yet parsed.
	Source string

	// Type overrides the type the path would imply. Empty means undeclared.
	Type string

	// ID overrides the id the path's leaf would imply. Empty means undeclared.
	ID string

	// Targets overrides the manifest's `harnesses` list for this asset. A nil
	// slice means undeclared; an empty non-nil slice means the author declared
	// an empty list, which is a validation error rather than a default, because
	// the asset could never be installed anywhere.
	Targets []string

	// Scope overrides the default `project` scope. Empty means undeclared.
	Scope string
}

package manifest

import (
	"fmt"
	"path/filepath"
)

// DecodeError reports a manifest harnaas could not decode.
//
// One type covers every decoding failure — malformed JSON, an unknown field, a
// wrongly shaped field, a version this binary cannot read — because they all
// end in the same place: a person opening `harnaas.json` and editing one line.
// What differs between them is the sentence, not the shape, and the shape is
// what a caller would branch on.
type DecodeError struct {
	// Path is the manifest the failure came from. It is empty for a document
	// decoded from bytes, where the message falls back to naming the file.
	Path string

	// Problem states what is wrong, in one line.
	Problem string

	// Fix states the edit that resolves it. It is always an edit for a person to
	// make: harnaas does not write this file.
	Fix string

	// Line and Column locate the problem in the file, both 1-based, and are zero
	// where the failure has no single location — an entry named by its index, or
	// a version that is wrong wherever it was written.
	Line, Column int
}

// Error renders the location, the problem, a blank line, and the fix.
func (e *DecodeError) Error() string {
	return fmt.Sprintf("%s: %s\n\n%s", e.where(), e.Problem, e.Fix)
}

// where names the file and, where one is known, the line and column inside it,
// in the `file:line:column` form an editor and a terminal both make clickable.
func (e *DecodeError) where() string {
	name := e.Path
	if name == "" {
		name = FileName
	}
	if e.Line <= 0 {
		return name
	}
	return fmt.Sprintf("%s:%d:%d", name, e.Line, e.Column)
}

// NotFoundError reports a project with no manifest at its root.
//
// It is a distinct type because "there is no manifest yet" is not a broken
// manifest: it is the ordinary state of a project before `harnaas init`, and a
// caller may want to say something different about it.
type NotFoundError struct {
	// Root is the project root that was searched, so the message can show which
	// project harnaas resolved — the usual cause of surprise here is being in a
	// different repository than expected.
	Root string
}

// Error names the project searched and the command that creates the file.
func (e *NotFoundError) Error() string {
	return fmt.Sprintf(
		"no %s found in %s\n\n"+
			"Run `harnaas init` in that project to create one.",
		FileName, e.Root,
	)
}

// SubdirectoryError reports a `harnaas.json` below the project root.
//
// Such a file is an error rather than something harnaas quietly skips. A file
// with this name that harnaas ignores is worse than one it rejects: its author
// believes it is declaring assets, and every command silently disagrees.
// Merging it is not on the table either, since the effective asset set would
// then depend on which directory a command ran from, which is exactly the
// variation harnaas exists to remove.
type SubdirectoryError struct {
	// Path is the offending manifest's absolute path.
	Path string

	// Root is the project root, whose manifest is the only one harnaas reads.
	Root string
}

// Error names the file that will never be read and states the only manifest
// harnaas does read.
func (e *SubdirectoryError) Error() string {
	shown := e.Path
	if relative, err := filepath.Rel(e.Root, e.Path); err == nil {
		shown = filepath.ToSlash(relative)
	}

	return fmt.Sprintf(
		"found a second manifest at %s, which harnaas never reads\n\n"+
			"harnaas reads only the %s at the repository root (%s). "+
			"Move any entries you need into that file and delete %s.",
		shown, FileName, e.Root, shown,
	)
}

package manifest

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// rawDocument is the shape the strict pass decodes into.
//
// It differs from [Document] in two deliberate ways. `version` is a pointer, so
// a missing field is distinguishable from a declared `0`. `assets` is a slice of
// raw messages, so each entry is decoded separately with its index in hand: an
// entry has no other name, and encoding/json attaches no array index to the
// errors it returns.
type rawDocument struct {
	Version   *int              `json:"version"`
	Harnesses []string          `json:"harnesses"`
	Sources   map[string]string `json:"sources"`
	Assets    []json.RawMessage `json:"assets"`
}

// rawAsset is the object form of an asset entry. The accepted field set is
// exactly this struct, and decoding rejects anything else.
type rawAsset struct {
	Source  string   `json:"source"`
	Type    string   `json:"type"`
	ID      string   `json:"id"`
	Targets []string `json:"targets"`
	Scope   string   `json:"scope"`
}

// fieldShapes says what each field must be, in the words the author wrote it
// in rather than in Go's.
//
// Deriving these from the struct types by reflection would produce messages
// naming Go types — `[]string`, `map[string]string` — which describe harnaas's
// implementation rather than the JSON the author is looking at. Field names do
// not collide across the two structs, so one table serves both.
var fieldShapes = map[string]string{
	"version":   "an integer",
	"harnesses": "an array of harness names",
	"sources":   "an object mapping a source key to a source string",
	"assets":    "an array of asset entries",
	"source":    "a string",
	"type":      "a string",
	"id":        "a string",
	"targets":   "an array of harness names",
	"scope":     "a string",
}

// unknownFieldPrefix is how encoding/json spells a field the document declares
// and the struct does not.
//
// The standard library returns a bare error for this case rather than a type,
// so recognising it means matching its text. The match is a best effort:
// [locator.translate] falls through to reporting the error as written if the
// wording ever changes, which is a worse message but never a wrong one.
const unknownFieldPrefix = "json: unknown field "

// unknownOffset says a failure has no byte offset to report, so the message
// names the file without pretending to a location.
const unknownOffset = int64(-1)

// Decode decodes a manifest from bytes, without touching the filesystem.
//
// It is the whole of decoding; [Load] is this function plus finding the file.
func Decode(data []byte) (*Document, error) {
	return decode(data, "")
}

// decode reads the version, then decodes the rest strictly, then decodes each
// asset entry. Every failure returns a nil document: a partially decoded
// manifest declares a different asset set than the one in the file.
func decode(data []byte, path string) (*Document, error) {
	loc := locator{data: data, path: path}

	version, err := decodeVersion(data, loc)
	if err != nil {
		return nil, err
	}

	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()

	var raw rawDocument
	if decodeErr := decoder.Decode(&raw); decodeErr != nil {
		return nil, loc.translate(decodeErr, decoder.InputOffset())
	}

	document := &Document{
		Path:      path,
		Version:   version,
		Harnesses: raw.Harnesses,
		Sources:   raw.Sources,
		Assets:    make([]AssetEntry, 0, len(raw.Assets)),
	}
	for index, rawEntry := range raw.Assets {
		entry, entryErr := decodeAssetEntry(index, rawEntry, loc)
		if entryErr != nil {
			return nil, entryErr
		}
		document.Assets = append(document.Assets, entry)
	}

	return document, nil
}

// decodeVersion reads `version` on its own, leniently, before anything else.
//
// Reading it inside the strict pass would report a manifest from a newer
// harnaas as an unknown field — the first field this binary does not know,
// which is an arbitrary one — and send the author looking for a typo in a file
// that has none. Read first, the same manifest produces the one message that
// helps: upgrade.
//
// The pass reads the whole document rather than streaming, which also settles
// trailing data: json.Unmarshal rejects a second top-level value, where a
// decoder would stop at the end of the first and silently drop the rest.
func decodeVersion(data []byte, loc locator) (int, error) {
	var probe struct {
		Version *int `json:"version"`
	}
	if err := json.Unmarshal(data, &probe); err != nil {
		return 0, loc.translate(err, unknownOffset)
	}

	switch {
	case probe.Version == nil:
		return 0, loc.fail(
			fmt.Sprintf("the manifest declares no %q field", "version"),
			fmt.Sprintf(`Add "version": %d as the first field of %s.`, SupportedVersion, FileName),
		)
	case *probe.Version > SupportedVersion:
		return 0, loc.fail(
			fmt.Sprintf(
				"the manifest declares version %d and this harnaas understands version %d, so it was written by a newer harnaas",
				*probe.Version, SupportedVersion,
			),
			"Upgrade harnaas to a version that understands this manifest.",
		)
	case *probe.Version < SupportedVersion:
		return 0, loc.fail(
			fmt.Sprintf("the manifest declares version %d, which is not a manifest version harnaas defines", *probe.Version),
			fmt.Sprintf(`Set "version": %d in %s.`, SupportedVersion, FileName),
		)
	}

	return *probe.Version, nil
}

// decodeAssetEntry decodes one entry in whichever form it was written.
//
// The form is chosen from the first non-space byte rather than by attempting a
// string decode and falling back to an object one, so an entry that is neither
// is reported as what it is instead of as a failed decode of a form its author
// never used.
func decodeAssetEntry(index int, raw json.RawMessage, loc locator) (AssetEntry, error) {
	entryLoc := loc.forAsset(index)

	trimmed := bytes.TrimLeft(raw, " \t\r\n")
	if len(trimmed) == 0 {
		return AssetEntry{}, entryLoc.fail(entryLoc.subject()+" is empty", assetFormFix)
	}

	switch trimmed[0] {
	case '"':
		var source string
		if err := json.Unmarshal(raw, &source); err != nil {
			return AssetEntry{}, entryLoc.translate(err, unknownOffset)
		}
		return AssetEntry{Index: index, Source: source}, nil

	case '{':
		decoder := json.NewDecoder(bytes.NewReader(raw))
		decoder.DisallowUnknownFields()

		var object rawAsset
		if err := decoder.Decode(&object); err != nil {
			return AssetEntry{}, entryLoc.translate(err, unknownOffset)
		}
		return AssetEntry{
			Index:      index,
			ObjectForm: true,
			Source:     object.Source,
			Type:       object.Type,
			ID:         object.ID,
			Targets:    object.Targets,
			Scope:      object.Scope,
		}, nil

	default:
		return AssetEntry{}, entryLoc.fail(
			entryLoc.subject()+" is neither a source string nor an object",
			assetFormFix,
		)
	}
}

// assetFormFix states both accepted entry forms, which is the fix for every
// entry that is neither.
var assetFormFix = fmt.Sprintf(
	"Write the entry in %s either as a source string, such as \"acme:skills/review\", "+
		"or as an object with a \"source\" field.",
	FileName,
)

// locator turns an encoding/json failure into a harnaas diagnostic, and a byte
// offset into the line and column an author can navigate to.
//
// A locator is scoped either to the whole document or, through [forAsset], to
// one asset entry, which is what decides whether a message says "the manifest"
// or names the entry.
type locator struct {
	data []byte
	path string

	// entry names the asset entry this locator's bytes came from, and is nil
	// for the document as a whole.
	entry *int
}

// forAsset returns a locator scoped to one asset entry.
func (l locator) forAsset(index int) locator {
	l.entry = &index
	return l
}

// subject names what a message is about: the manifest, or one entry in it.
func (l locator) subject() string {
	if l.entry == nil {
		return "the manifest"
	}
	return fmt.Sprintf("the asset entry at index %d", *l.entry)
}

// qualifier attributes a field to its asset entry, and is empty at document
// scope, where a field name is already unambiguous.
func (l locator) qualifier() string {
	if l.entry == nil {
		return ""
	}
	return " of " + l.subject()
}

// fail reports a problem with no single location in the file.
func (l locator) fail(problem, fix string) *DecodeError {
	return l.failAt(unknownOffset, problem, fix)
}

// failAt reports a problem at a byte offset into the document.
func (l locator) failAt(offset int64, problem, fix string) *DecodeError {
	line, column := l.locate(offset)
	return &DecodeError{Path: l.path, Problem: problem, Fix: fix, Line: line, Column: column}
}

// translate converts an encoding/json failure into a diagnostic naming what is
// wrong and the edit that fixes it.
//
// fallback supplies a byte offset for the failures the standard library reports
// without one; it is [unknownOffset] where the caller has none either.
func (l locator) translate(err error, fallback int64) *DecodeError {
	var syntaxErr *json.SyntaxError
	if errors.As(err, &syntaxErr) {
		return l.failAt(syntaxErr.Offset,
			fmt.Sprintf("%s is not valid JSON: %s", l.subject(), syntaxErr.Error()),
			fmt.Sprintf("Correct the JSON at that position in %s.", FileName),
		)
	}

	if errors.Is(err, io.ErrUnexpectedEOF) || errors.Is(err, io.EOF) {
		return l.failAt(fallback,
			l.subject()+" ends in the middle of a JSON value",
			fmt.Sprintf("Complete the JSON in %s — a bracket or brace is likely unclosed.", FileName),
		)
	}

	var typeErr *json.UnmarshalTypeError
	if errors.As(err, &typeErr) {
		return l.wrongShape(typeErr)
	}

	if field, ok := unknownField(err); ok {
		return l.failAt(fallback,
			fmt.Sprintf("%s has the unknown field %q", l.subject(), field),
			fmt.Sprintf(
				"Remove or correct %q in %s. harnaas rejects a field it does not know because in a hand-edited file it is almost always a misspelling.",
				field, FileName,
			),
		)
	}

	return l.failAt(fallback,
		fmt.Sprintf("%s could not be decoded: %s", l.subject(), err.Error()),
		fmt.Sprintf("Correct %s and run the command again.", FileName),
	)
}

// wrongShape reports a field whose value is not the shape the manifest format
// gives it.
func (l locator) wrongShape(err *json.UnmarshalTypeError) *DecodeError {
	if err.Field == "" {
		return l.failAt(err.Offset,
			fmt.Sprintf("%s must be a JSON object, and this one is %s", l.subject(), article(err.Value)),
			fmt.Sprintf("Make the top level of %s an object with a \"version\" field.", FileName),
		)
	}

	shape, known := fieldShapes[err.Field]
	if !known {
		return l.failAt(err.Offset,
			fmt.Sprintf("the %q field%s is %s, which is not the shape harnaas expects there",
				err.Field, l.qualifier(), article(err.Value)),
			fmt.Sprintf("Correct the %q field in %s.", err.Field, FileName),
		)
	}

	return l.failAt(err.Offset,
		fmt.Sprintf("the %q field%s must be %s, and this one is %s",
			err.Field, l.qualifier(), shape, article(err.Value)),
		fmt.Sprintf("Edit %s so %q is %s.", FileName, err.Field, shape),
	)
}

// locate converts a byte offset into a 1-based line and column, or two zeroes
// where there is no offset to convert.
//
// An entry-scoped locator never reports a location: its entry was decoded from
// its own bytes, so every offset in the failure counts from the start of the
// entry and would name a line elsewhere in the file. Naming the entry's index
// is the honest answer, and a plausible line:column pointing at the wrong line
// is worse than none.
//
// encoding/json reports the offset *after* the byte it stopped on, so the
// reported position steps back one to name that byte rather than the one
// following it.
func (l locator) locate(offset int64) (line, column int) {
	if l.entry != nil || offset <= 0 || offset > int64(len(l.data)) {
		return 0, 0
	}

	line, column = 1, 1
	for _, b := range l.data[:offset-1] {
		if b == '\n' {
			line++
			column = 1
			continue
		}
		column++
	}
	return line, column
}

// unknownField extracts the field name from encoding/json's unknown-field
// error, reporting whether the error was one.
func unknownField(err error) (string, bool) {
	message := err.Error()
	if !strings.HasPrefix(message, unknownFieldPrefix) {
		return "", false
	}

	name, unquoteErr := strconv.Unquote(strings.TrimPrefix(message, unknownFieldPrefix))
	if unquoteErr != nil {
		return "", false
	}
	return name, true
}

// article prefixes a JSON type name as encoding/json spells it — "string",
// "number", "array" — with the article that makes it read as a sentence.
func article(jsonType string) string {
	if jsonType == "" {
		return "a value of another type"
	}
	if strings.ContainsRune("aeiou", rune(jsonType[0])) {
		return "an " + jsonType
	}
	return "a " + jsonType
}

	require.ErrorIs(t, err, paths.ErrRootNotEstablished)

	_, err = manifest.Path(t.Context())
	require.ErrorIs(t, err, paths.ErrRootNotEstablished)
}

// TestPackageNeverWrites asserts by construction what the manifest's read-only
// rule states: apart from `init` creating the file once, harnaas never writes,
// reformats or normalizes `harnaas.json`.
//
// The rule is what makes the manifest's diffs trustworthy — a reviewer can tell
// an intentional pin bump from a normalization pass — and it is the reason
// every remedy here is phrased as an edit. A write added to this package would
// break that quietly, in a change whose diff would look like a convenience.
func TestPackageNeverWrites(t *testing.T) {
	t.Parallel()

	banned := map[string]bool{
		"WriteFile": true, "Create": true, "CreateTemp": true, "OpenFile": true,
		"Remove": true, "RemoveAll": true, "Rename": true, "Truncate": true,
		"Mkdir": true, "MkdirAll": true, "Chmod": true, "WriteString": true,
	}

	entries, err := os.ReadDir(".")
	require.NoError(t, err)

	fset := token.NewFileSet()
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}

		file, parseErr := parser.ParseFile(fset, name, nil, parser.SkipObjectResolution)
		require.NoError(t, parseErr)

		for _, imported := range file.Imports {
			assert.NotContains(t, imported.Path.Value, "jsonutil",
				"%s imports the atomic writer; nothing here may write the manifest", name)
		}

		ast.Inspect(file, func(node ast.Node) bool {
			selector, ok := node.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			assert.False(t, banned[selector.Sel.Name],
				"%s calls %s; the manifest is read-only outside `harnaas init`", name, selector.Sel.Name)
			return true
		})
	}
}

